"""Method selection from sealed matched results only; no model/scorer/GT reader."""
from pathlib import Path
import math,sys
ROOT=Path(__file__).resolve().parents[1];sys.path.insert(0,str(ROOT))
from scripts.stvg_native_instance_common_v1 import read,write,sha
H=ROOT/'artifacts/stvg_native_head_adapter32_v1/readout002';Q=ROOT/'artifacts/stvg_qwen35_geometry32_v1';T=ROOT/'artifacts/stvg_qwen_b3_temporal32_v1/processor448002';OUT=ROOT/'results/stvg_qwen_temporal/2026-10-17/b3_matched32_448'
def main():
    data={k:read(b/'POSTSEAL_RESULTS.json')for k,b in [('H',H),('Q',Q),('T',T)]};rr=read(T/'ROSTER_LOCK.json')['records'];ids=[r['probe_alias']for r in rr]
    for k,b in [('H',H),('Q',Q),('T',T)]:assert data[k]['count']==32 and read(b/'CPU_COMPLETION.json')['result_sha256']==sha(b/'POSTSEAL_RESULTS.json')and [r['probe_alias']for r in read(b/'ROSTER_LOCK.json')['records']]==ids
    def v(group,ds,arm,key='m_vIoU'):return next(s['mean']for s in data[group]['summary']if s['dataset']==ds and s['arm']==arm and s['metric']==key)
    lines=['# Native heads and frozen Teacher choice: fixed development32','','Same exposed HC16/Vid16, not independent confirmation. No production/PAPER change. Each question below has its own matched comparator; rows from different temporal supports are not merged into a winner score.','','## Parameter interface','','Native Temporal256x2 is the previous B3 residual expressed at the actual native head input, exactly verified rather than treated as a separate fit. Native Spatial256x4 changes the parameter interface, freezing the old1792 Query/LN parameters. Same references, Gaussian/optimizer/acceptance. Fixed-T2-clock comparison:','','|Adapter|HC vIoU %|Vid vIoU %|','|---|---:|---:|']
    for a,label in [('ORIGINAL_S_FIXED_CLOCK','Original Query+LN1792'),('NEW_S_FIXED_CLOCK','Native box-head residual1024')]:lines.append(f'|{label}|{100*v("H","hc2",a):.6f}|{100*v("H","vidstg",a):.6f}|')
    lines+=['','Shared nonanchor influence/gradient/Source restoration and actual full-frame decoding are established engineering properties. This one fixed no-retuning configuration has lower mean geometry/localization than the old interface; it is not a demonstrated quality upgrade, nor proof all head adapters fail. Simplicity versus observed loss is an architecture tradeoff. Retain the original interface as the quality reference; no automatic LR/adapter search or promotion.','','## Spatial Teacher, original Student and same T2 clock','','|Teacher/use|HC vIoU %|Vid vIoU %|','|---|---:|---:|']
    for a,label in [('T2','No spatial adaptation'),('R1_FIXED_OPD','Revised R1 Direct + original OPD'),('QWEN_OPD','Qwen Direct + original OPD'),('R1_FIXED_D2','R1 same-reference parameter-free D2'),('QWEN_D2','Qwen same-reference parameter-free D2')]:lines.append(f'|{label}|{100*v("Q","hc2",a):.6f}|{100*v("Q","vidstg",a):.6f}|')
    lines+=['','Qwen Direct has higher OPD point means than R1 on this32, but paired intervals cross zero and source tails remain. Qwen D2 has a higher HC mean than Qwen OPD and lower Vid mean; no per-domain splicing or claim that parameter adaptation is already indispensable. Keep both uses as matched evidence, Qwen as a candidate rather than a confirmed method winner.','','## Temporal Teacher, same B3 hypotheses and Student','','|Temporal readout|HC vIoU %|Vid vIoU %|','|---|---:|---:|']
    for a,label in [('Frozen','Original Frozen decoder'),('MARGINAL_NO_UPDATE','Source marginal MAP, no update'),('R1_B3','R1 B3'),('QWEN_B3','Qwen B3, matched eight448'),('QWEN_TARGET_HARD','Qwen tilted target, no-parameter hard readout')]:lines.append(f'|{label}|{100*v("T","hc2",a):.6f}|{100*v("T","vidstg",a):.6f}|')
    lines+=['','This isolates the whole caption+alignment Teacher family under the same hypotheses/raw pixels/448 sampling resolution, reward task and Student. Native patch grids/tokenizers differ between model architectures; actual vision and text costs are reported, not assumed equal. The earlier Qwen128-resolution pilot is preserved as an input-budget error and excluded from the matched Teacher conclusion.','','The correct adaptation comparison is each fitted Teacher version versus Source marginal MAP. A change from original Frozen also includes decoding. Full256 published marginal readout results and this development32 have different cohort means; never combine them or select a decoder from target GT. Query Consistency remains the intended mechanism but requires an incremental effect beyond the same-decoder control.','','## Whole system and cost boundary','','R1/R1, Qwen/Qwen, R1/Qwen and Qwen/R1 freshly linked Full are NOT all measured here. Spatial evidence is fixed to the previous T2 observation clock; new Temporal output would change acquisition times. Combining stored boxes with a new interval is a fixed-evidence diagnostic, not proof a freshly acquired single-Teacher pipeline works. Do not report a complete2x2 Teacher Full table or sum branch means into one. This round does not auto-launch mixed Full, cross-backbone, official fullset or new tuning.','','COST.json files include actual calls/tokens/stage walls and failed engineering loads. Reused evidence is not zero historical cost; cold/hot and different inference backends are not a controlled latency benchmark. Source checkpoint and Teacher training-domain overlap remain separate from inference-time no-GT access. The semantic512 panel remains44 model-assisted/468pending; displayed input/output engineering panels add no independent identity/role annotations.','','Completed prior public groups: [head32](https://github.com/Zonglin-He/A/commit/820c6a584c2ee949e08dc8fceb74b13d4b267c8e), [Qwen Direct32](https://github.com/Zonglin-He/A/commit/f49d9ab52d8d8fb90e1b4368fea557c3b9fd4c1d).']
    (OUT/'METHOD_SELECTION.md').write_text('\n'.join(lines)+'\n')
    write(OUT/'METHOD_SELECTION.json',dict(status='finite_development_comparison_complete',count=32,Temporal_interface='existing512 exactly represented at native head',Spatial_adapter='1024 engineering pass; lower means in fixed config, no quality promotion',Spatial_Teacher='Qwen promising Direct candidate, not independently confirmed',Temporal_Teacher='compare actual same-decoder increment; no automatic winner or mixed Full',mixed_fresh_Full_2x2_measured=False,CURRENT_changed=False,backbone_generalization_measured=False,semantic512_complete=False,source_result_sha256={k:sha(b/'POSTSEAL_RESULTS.json')for k,b in [('head32',H),('Qwen_Direct32',Q),('Qwen_Temporal32',T)]}))
    # Retain all public low-resolution pilot rows, explicitly labeled diagnostic.
    pilot=OUT/'pilot_low_resolution';pilot.mkdir();old=ROOT/'results/stvg_qwen_temporal/2026-10-17/b3_matched32'
    for name in ['RESULTS.json','COST.json','ROOT_SCALAR_READBACK.json']:(pilot/name).write_bytes((old/name).read_bytes())
    (pilot/'SCOPE.md').write_text('Input-contract pilot only: copying a per-frame pixel limit to a total-video budget caused128resolution/64vision tokens per clip. Not the matched448 Teacher comparison. All32 rows, tails and calls remain; correction was selected from processor-code/token evidence before consulting these scores.\n')
    receipt=read(T/'ACTUAL_TOKEN_READBACK.json');write(OUT/'ACTUAL_TOKEN_READBACK.json',receipt);cost=read(OUT/'COST.json');cost.update(actual_caption_input_tokens=receipt['caption_input_tokens'],actual_caption_video_tokens=receipt['caption_video_tokens'],actual_caption_generated_tokens=receipt['caption_generated_tokens'],actual_extra_prefix_qualifications=receipt['extra_prefix_qualification'],previous_pilot_cost_included=True,Teacher_interface_evidence_not_free=True);write(OUT/'COST.json',cost,mutable=True)
    manifest=T/'publication/temporal32/EXPORT_MANIFEST.json';m=read(manifest);paths=set(m['paths'])|{str(p.relative_to(ROOT))for p in OUT.rglob('*')if p.is_file()};m.update(paths=sorted(paths),files=[dict(path=p,sha256=sha(ROOT/p),bytes=(ROOT/p).stat().st_size)for p in sorted(paths)]);write(manifest,m,mutable=True)
    print('METHOD_SELECTION_AND_PILOT_READY')
if __name__=='__main__':main()
